const exactTranslations = new Map(translations);
const substringTranslations = [...translations].sort((left, right) => right[0].length - left[0].length);

export function termText(value: RichText | undefined, locale: Locale): string {
  const source = textForLocale(value, locale);
  if (locale !== "en-US" || !/[\u3400-\u9fff]/u.test(source)) return source;
  const exact = exactTranslations.get(source);
  if (exact) return exact;
  return substringTranslations.reduce((result, [zhCN, enUS]) => result.replaceAll(zhCN, enUS), source);
}
